css:
body :where([data-bz-node="ai"]) .bz-block{padding:0}
body :where([data-bz-node="ai"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="ai"]>.bz-container{padding-inline:0}

body [data-bz-node="ai"]{background:#fff;padding:90px 0}
body [data-bz-node="ai"]>.bz-container{max-width:var(--container)}
body [data-bz-node="ai-row"]{display:grid;grid-template-columns:1fr 1fr;gap:0 64px;align-items:center}
body [data-bz-node="ai-copy"],body [data-bz-node="ai-media"]{grid-column:auto}
body [data-bz-node="ai-h"] h2{font:700 36px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;max-width:520px}
body [data-bz-node="ai-sub"] h3{font:700 20px/1.2 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:24px 0 0;max-width:520px}
body [data-bz-node="ai-text"] .bz-text{max-width:520px;margin-top:20px}
body [data-bz-node="ai-text"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0 0 14px}
body [data-bz-node="ai-text"] p:last-child{margin:0}
body [data-bz-node="ai-text"] a{color:var(--accent);text-decoration:none}
body [data-bz-node="ai-text"] a:hover{text-decoration:underline}
body [data-bz-node="ai-media"] figure{margin:0}
body [data-bz-node="ai-media"] img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:0}
@media (max-width:1100px){body [data-bz-node="ai"]{padding:64px 24px}body [data-bz-node="ai-row"]{grid-template-columns:1fr;gap:32px}body [data-bz-node="ai-h"] h2{font-size:30px}}
@media (max-width:640px){body [data-bz-node="ai"]{padding:48px 20px}body [data-bz-node="ai-h"] h2{font-size:26px}body [data-bz-node="ai-sub"] h3{font-size:17px}}
